            if r is None: continue
            s1,l1=r; r=apply_ann(l1,dd)
            if r is None: continue
            s2,l2=r; r=apply_cre(l2,b)
            if r is None: continue
            s3,l3=r; r=apply_cre(l3,a)
            if r is None: continue
            s4,l4=r
            H[idx[tuple(l4)],j]+=0.5*s1*s2*s3*s4*Vo[a//2,cc//2,b//2,dd//2]
